import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from specs5 import *

COMP = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
RNA_CODONS = {'AUG': 'Met', 'AGU': 'Ser', 'AAA': 'Lys', 'GGA': 'Gly', 'GAA': 'Glu', 'CUU': 'Leu', 'UUU': 'Phe', 'UAA': 'Stop'}

# ═════════════════════════ INHERIT: traits you can see in everyday life ═════════════════════════

inh_earwax = inh_spec('inh-earwax', B('Wet or dry earwax', 'Cera de oído húmeda o seca'), B('A trait you can check on yourself', 'Un rasgo que puedes comprobar en ti'), 'beginner', 5, 'cell',
    B('Fill in the Punnett squares for earwax: the wet type is dominant and dry earwax needs two copies of the changed allele.', 'Rellena los cuadros de Punnett de la cera del oído: el tipo húmedo es dominante y la cera seca necesita dos copias del alelo cambiado.'),
    B('Some people have sticky, yellow-brown earwax and others have dry, flaky, grey earwax. It is one of the few human traits that follows the simple rules of Mendel almost perfectly.', 'Unas personas tienen cera pegajosa de color amarillo pardo y otras tienen cera seca, escamosa y grisácea. Es uno de los pocos rasgos humanos que siguen casi a la perfección las reglas simples de Mendel.'),
    org('human-earwax', 'People', 'Personas', 'Homo sapiens', B('A species with two kinds of earwax.', 'Una especie con dos tipos de cera de oído.'), MAMMAL + ['Primates', 'Hominidae', 'Homo'], tissue='ear canal'),
    [ex('cell', B('Two kinds', 'Dos tipos'), B('Wet and dry', 'Húmeda y seca'), B('Most people in the world have wet earwax. Dry earwax is common in people of East Asian descent and much rarer elsewhere.', 'La mayoría de las personas del mundo tiene la cera húmeda. La cera seca es frecuente en personas de ascendencia asiática oriental y mucho más rara en otros lugares.')),
     ex('dna', B('The allele', 'El alelo'), B('One letter in a transporter gene', 'Una letra en un gen transportador'), B('A single-letter change in a gene called ABCC11 makes its protein stop working. Wet earwax needs the working protein, so dry earwax needs two changed copies.', 'Un cambio de una sola letra en un gen llamado ABCC11 hace que su proteína deje de funcionar. La cera húmeda necesita la proteína que funciona, así que la seca necesita dos copias cambiadas.'))],
    dict(trait=B('Earwax', 'Cera del oído'), alleles=['W', 'w'], phenotypes={'WW': 'wet', 'Ww': 'wet', 'ww': 'dry'},
         labels={'wet': B('Wet earwax', 'Cera húmeda'), 'dry': B('Dry earwax', 'Cera seca')},
         scenarios=[
             sc('WW', 'ww', B('Wet (two wet alleles)', 'Húmeda (dos alelos húmedos)'), B('Dry', 'Seca'), B('A person with wet earwax (WW) and a person with dry earwax (ww) have a child. What is the probability that the child has wet earwax?', 'Una persona con cera húmeda (WW) y otra con cera seca (ww) tienen un hijo. ¿Qué probabilidad hay de que tenga cera húmeda?'), 'wet',
                B('All four cells are Ww and W hides w: the child always has wet earwax (100%).', 'Las cuatro casillas son Ww y W oculta a w: el hijo siempre tiene cera húmeda (100 %).')),
             sc('Ww', 'Ww', B('Wet, carries w', 'Húmeda, lleva w'), B('Wet, carries w', 'Húmeda, lleva w'), B('Two people with wet earwax who both carry the dry allele have a child. What is the probability that the child has dry earwax?', 'Dos personas con cera húmeda que llevan las dos el alelo seco tienen un hijo. ¿Qué probabilidad hay de que tenga cera seca?'), 'dry',
                B('Only the ww cell is dry: 25%. Two wet parents can have a dry-eared child.', 'Solo la casilla ww es seca: 25 %. Dos progenitores con cera húmeda pueden tener un hijo con cera seca.')),
             sc('Ww', 'Ww', B('Wet, carries w', 'Húmeda, lleva w'), B('Wet, carries w', 'Húmeda, lleva w'), B('Same parents as before. What is the probability that the child has wet earwax?', 'Los mismos progenitores de antes. ¿Qué probabilidad hay de que el hijo tenga cera húmeda?'), 'wet',
                B('WW, Ww and wW all have a W: three cells out of four, 75%.', 'WW, Ww y wW tienen una W: tres casillas de cuatro, 75 %.'))]),
    [B('Fill the square first; then look at each cell: does it have at least one W?', 'Rellena primero el cuadro; luego mira cada casilla: ¿tiene al menos una W?'),
     B('W is dominant: WW and Ww are wet. Only ww is dry.', 'W es dominante: WW y Ww son húmedas. Solo ww es seca.'),
     B('Count the cells of the earwax asked about: each is worth 25%.', 'Cuenta las casillas de la cera por la que preguntan: cada una vale un 25 %.')],
    **closing(B('A trait in your own ear', 'Un rasgo en tu propio oído'),
              B('You saw that dry earwax can appear in a family where both parents have wet earwax, as long as both carry the changed allele.', 'Has visto que la cera seca puede aparecer en una familia donde los dos progenitores tienen cera húmeda, siempre que los dos lleven el alelo cambiado.'),
              B('Because the trait is so simple and so easy to see, it has been used to study how human populations moved and mixed.', 'Como el rasgo es tan simple y tan fácil de ver, se ha usado para estudiar cómo se movieron y se mezclaron las poblaciones humanas.'),
              B('In 2006 a team in Japan showed that a single-letter change in the ABCC11 gene decides the type of earwax. The same protein works in the sweat glands of the armpit, which is why the dry-earwax change is also linked to weaker body odour.', 'En 2006 un equipo de Japón mostró que un cambio de una sola letra en el gen ABCC11 decide el tipo de cera. La misma proteína trabaja en las glándulas sudoríparas de la axila, por eso el cambio de la cera seca también se asocia a un olor corporal más débil.'),
              B('The changed allele alters one amino acid of ABCC11, a protein that moves molecules out of cells. Without a working protein, the gland releases less of the substances that make earwax wet and sticky.', 'El alelo cambiado altera un aminoácido de ABCC11, una proteína que saca moléculas de las células. Sin la proteína que funciona, la glándula libera menos de las sustancias que hacen la cera húmeda y pegajosa.'),
              B('Only one gene is followed. The frequencies of the alleles differ a lot between populations.', 'Solo se sigue un gen. Las frecuencias de los alelos cambian mucho de unas poblaciones a otras.'),
              [ref(['Yoshiura, K.', 'Kinoshita, A.', 'Ishida, T.', 'et al.'], 2006, 'A SNP in the ABCC11 gene is the determinant of human earwax type', 'Nature Genetics', '10.1038/ng1733')]))

inh_siamese = inh_spec('inh-siamese', B('Why Siamese cats have dark paws', 'Por qué los gatos siameses tienen las patas oscuras'), B('A recessive allele that likes the cold', 'Un alelo recesivo al que le gusta el frío'), 'intermediate', 6, 'cell',
    B('Fill in the Punnett squares for cat colour: dark all over is dominant and the Siamese pattern needs two copies of the changed allele.', 'Rellena los cuadros de Punnett del color de los gatos: oscuro por todo el cuerpo es dominante y el patrón siamés necesita dos copias del alelo cambiado.'),
    B('A Siamese cat is pale on the body and dark on its ears, face, paws and tail. The cause is an enzyme that works only in the cooler parts of the body.', 'Un gato siamés es claro en el cuerpo y oscuro en las orejas, la cara, las patas y la cola. La causa es una enzima que solo funciona en las partes más frías del cuerpo.'),
    org('cat-siamese', 'Domestic cat', 'Gato doméstico', 'Felis catus', B('A pet with many coat patterns.', 'Una mascota con muchos patrones de pelaje.'), MAMMAL + ['Carnivora', 'Felidae', 'Felis'], tissue='skin'),
    [ex('cell', B('The pattern', 'El patrón'), B('Dark where it is cool', 'Oscuro donde hace fresco'), B('Kittens are born pale all over. The pigment appears later, only in the cooler extremities, as the cat grows.', 'Los gatitos nacen claros por todas partes. El pigmento aparece después, solo en las extremidades más frías, a medida que el gato crece.')),
     ex('dna', B('The allele', 'El alelo'), B('A heat-shy enzyme', 'Una enzima sensible al calor'), B('The Siamese allele changes tyrosinase, the enzyme that makes the dark pigment. The changed enzyme works only when it is cool. Two changed copies are needed for the pattern.', 'El alelo siamés cambia la tirosinasa, la enzima que fabrica el pigmento oscuro. La enzima cambiada solo funciona cuando hace fresco. Se necesitan dos copias cambiadas para el patrón.'))],
    dict(trait=B('Coat pattern', 'Patrón del pelaje'), alleles=['C', 'c'], phenotypes={'CC': 'full', 'Cc': 'full', 'cc': 'pointed'},
         labels={'full': B('Dark all over', 'Oscuro por todo el cuerpo'), 'pointed': B('Siamese pattern', 'Patrón siamés')},
         scenarios=[
             sc('cc', 'cc', B('Siamese', 'Siamés'), B('Siamese', 'Siamés'), B('Two Siamese cats (cc) have kittens. What is the probability that a kitten has the Siamese pattern?', 'Dos gatos siameses (cc) tienen gatitos. ¿Qué probabilidad hay de que un gatito tenga el patrón siamés?'), 'pointed',
                B('All four cells are cc: every kitten is Siamese (100%).', 'Las cuatro casillas son cc: todos los gatitos son siameses (100 %).')),
             sc('Cc', 'Cc', B('Dark, carries c', 'Oscuro, lleva c'), B('Dark, carries c', 'Oscuro, lleva c'), B('Two dark cats that both carry the Siamese allele have kittens. What is the probability of a Siamese kitten?', 'Dos gatos oscuros que llevan los dos el alelo siamés tienen gatitos. ¿Qué probabilidad hay de un gatito siamés?'), 'pointed',
                B('Only the cc cell is Siamese: 25%.', 'Solo la casilla cc es siamesa: 25 %.')),
             sc('Cc', 'cc', B('Dark, carries c', 'Oscuro, lleva c'), B('Siamese', 'Siamés'), B('A dark cat that carries c and a Siamese cat have kittens. What is the probability of a dark kitten?', 'Un gato oscuro que lleva c y un gato siamés tienen gatitos. ¿Qué probabilidad hay de un gatito oscuro?'), 'full',
                B('Two cells are Cc (dark) and two are cc (Siamese): 50% each.', 'Dos casillas son Cc (oscuras) y dos son cc (siamesas): 50 % cada una.'))]),
    [B('Fill the square first; then look at each cell: does it have at least one C?', 'Rellena primero el cuadro; luego mira cada casilla: ¿tiene al menos una C?'),
     B('C is dominant: CC and Cc are dark all over. Only cc has the Siamese pattern.', 'C es dominante: CC y Cc son oscuros por todo el cuerpo. Solo cc tiene el patrón siamés.'),
     B('Count the cells of the pattern asked about: each is worth 25%.', 'Cuenta las casillas del patrón por el que preguntan: cada una vale un 25 %.')],
    **closing(B('A coat that reads the temperature', 'Un pelaje que lee la temperatura'),
              B('You saw that a Siamese pattern needs two copies of the changed allele, and that two Siamese parents can only have Siamese kittens.', 'Has visto que el patrón siamés necesita dos copias del alelo cambiado, y que dos progenitores siameses solo pueden tener gatitos siameses.'),
              B('Cat breeders use these squares to plan litters, and the same idea of a temperature-sensitive enzyme appears in the fur of Siamese rabbits and Himalayan mice.', 'Quienes crían gatos usan estos cuadros para planificar camadas, y la misma idea de una enzima sensible a la temperatura aparece en el pelaje de los conejos himalayos y de algunos ratones.'),
              B('In 2005 researchers found that the Siamese and the Burmese patterns of the domestic cat come from different changes in the tyrosinase gene, and that both give an enzyme that is less active.', 'En 2005 unos investigadores hallaron que los patrones siamés y birmano del gato doméstico vienen de cambios distintos en el gen de la tirosinasa, y que los dos dan una enzima menos activa.'),
              B('A one-letter change swaps an amino acid of tyrosinase. The enzyme is stable and active only at lower temperatures, so pigment is made in the ears, paws, tail and face, and not in the warmer body.', 'Un cambio de una letra sustituye un aminoácido de la tirosinasa. La enzima es estable y activa solo a temperaturas bajas, así que el pigmento se fabrica en las orejas, las patas, la cola y la cara, y no en el cuerpo, más cálido.'),
              B('Cat coats depend on many genes; here only the gene of the Siamese pattern is followed.', 'El pelaje de los gatos depende de muchos genes; aquí solo se sigue el del patrón siamés.'),
              [ref(['Lyons, L. A.', 'Imes, D. L.', 'Rah, H. C.', 'Grahn, R. A.'], 2005, 'Tyrosinase mutations associated with Siamese and Burmese patterns in the domestic cat (Felis catus)', 'Animal Genetics', '10.1111/j.1365-2052.2005.01253.x')]))

# ═════════════════════════ MUTATION: one-letter changes you can notice ═════════════════════════

mut_bitter = mut_spec('mut-bitter', B('Why broccoli tastes bitter to some', 'Por qué el brócoli sabe amargo a algunos'), B('A swap in a taste receptor', 'Un cambio en un receptor del gusto'), 'intermediate', 5, 'plant',
    B('Bitter taste receptor gene (illustrative)', 'Gen de un receptor del gusto amargo (ilustrativo)'), 'ATGTTCACTCCAGAGGTAAGC', 'ATGTTCACTGCAGAGGTAAGC',
    B('A real discovery with an invented sequence. A receptor on the tongue detects a bitter compound found in broccoli and cabbage. A swap of one amino acid, proline for alanine, changes how well it works.', 'Un descubrimiento real con una secuencia inventada. Un receptor de la lengua detecta un compuesto amargo del brócoli y de la col. El cambio de un aminoácido, prolina por alanina, modifica lo bien que funciona.'),
    {'silent': B('Not here: the amino acid changes.', 'Aquí no: el aminoácido cambia.'),
     'missense': B('CCA (Pro) became GCA (Ala): one amino acid was swapped for another. In the real receptor, this swap and two more change how strongly a person tastes the bitterness of some vegetables.', 'CCA (Pro) pasó a GCA (Ala): un aminoácido se cambió por otro. En el receptor real, este cambio y otros dos modifican cuánto amargor nota una persona en algunas verduras.'),
     'nonsense': B('Not here: no stop signal appears.', 'Aquí no: no aparece ninguna señal de fin.')},
    [ex('plant', B('Taste', 'Gusto'), B('Same dish, different taste', 'El mismo plato, distinto sabor'), B('Some people find broccoli, cabbage and Brussels sprouts very bitter, and others hardly notice it. Part of the difference is in a gene.', 'A unas personas el brócoli, la col y las coles de Bruselas les parecen muy amargos y otras casi no lo notan. Parte de la diferencia está en un gen.')),
     ex('dna', B('A swap', 'Un cambio'), B('Proline to alanine', 'De prolina a alanina'), B('The gene TAS2R38 makes a receptor on the tongue. Common versions of the gene differ in three amino acids, and together they make a strong or a weak receptor.', 'El gen TAS2R38 fabrica un receptor de la lengua. Las versiones comunes del gen difieren en tres aminoácidos, y juntos hacen un receptor fuerte o débil.'))],
    [B('Compare the two rows letter by letter. Only one is different.', 'Compara las dos filas letra a letra. Solo una es distinta.'),
     B('Look at the codon that contains the changed letter, before and after.', 'Mira el codón que contiene la letra cambiada, antes y después.'),
     B('The change is in the fourth codon: CCA became GCA, so Pro became Ala (missense).', 'El cambio está en el cuarto codón: CCA pasó a GCA, así que Pro pasó a Ala (de sentido erróneo).')],
    org('taster-gene', 'Taste receptor', 'Receptor del gusto', 'Homo sapiens', B('A protein on the tongue that detects bitter compounds.', 'Una proteína de la lengua que detecta compuestos amargos.'), MAMMAL + ['Primates', 'Hominidae', 'Homo'], tissue='tongue'),
    **closing(B('A swap that changes dinner', 'Un cambio que altera la cena'),
              B('You found a one-letter change that swaps an amino acid and changes how bitter a vegetable tastes.', 'Has encontrado un cambio de una letra que sustituye un aminoácido y modifica lo amargo que sabe una verdura.'),
              B('Taste genes help to explain why people like different foods, and food companies study them to design products that more people enjoy.', 'Los genes del gusto ayudan a explicar por qué a la gente le gustan comidas distintas, y las empresas de alimentación los estudian para diseñar productos que gusten a más personas.'),
              B('In 2003 a team identified TAS2R38 as the gene behind the ability to taste certain bitter compounds, such as the ones found in cabbage-family vegetables. Three amino acid swaps are common in the population.', 'En 2003 un equipo identificó TAS2R38 como el gen de la capacidad de notar ciertos compuestos amargos, como los de las verduras de la familia de la col. Tres cambios de aminoácidos son frecuentes en la población.'),
              B('A missense mutation swaps one amino acid for another. In a receptor, a swap in the right place changes how strongly the protein binds the bitter molecule.', 'Una mutación de sentido erróneo cambia un aminoácido por otro. En un receptor, un cambio en el lugar adecuado modifica con qué fuerza la proteína se une a la molécula amarga.'),
              [B('The real change is the one described, but the sequence around it is an invented short example.', 'El cambio real es el que se describe, pero la secuencia que lo rodea es un ejemplo corto inventado.')],
              [ref(['Kim, U.-K.', 'Jorgenson, E.', 'Coon, H.', 'Leppert, M.', 'Risch, N.', 'Drayna, D.'], 2003, 'Positional cloning of the human quantitative trait locus underlying taste sensitivity to phenylthiocarbamide', 'Science', '10.1126/science.1080190')]))

mut_mc1r = mut_spec('mut-mc1r', B('The gene behind red hair', 'El gen del pelo rojo'), B('A swap that turns the pigment down', 'Un cambio que baja el pigmento'), 'intermediate', 5, 'cell',
    B('Pigment receptor gene (illustrative)', 'Gen de un receptor del pigmento (ilustrativo)'), 'ATGGCACGCTTCGAGGTC', 'ATGGCATGCTTCGAGGTC',
    B('A real change with an invented sequence. A receptor called MC1R tells skin and hair cells to make dark pigment. A swap of arginine for cysteine in it makes the receptor work less, and the hair comes out red.', 'Un cambio real con una secuencia inventada. Un receptor llamado MC1R ordena a las células de la piel y del pelo que fabriquen pigmento oscuro. El cambio de arginina por cisteína lo hace trabajar menos, y el pelo sale rojo.'),
    {'silent': B('Not here: the amino acid changes.', 'Aquí no: el aminoácido cambia.'),
     'missense': B('CGC (Arg) became TGC (Cys): one amino acid was swapped for another. This real change, called R151C, lowers the activity of the receptor, so the cells make less dark pigment and more of the red-yellow one.', 'CGC (Arg) pasó a TGC (Cys): un aminoácido se cambió por otro. Este cambio real, llamado R151C, reduce la actividad del receptor, así que las células fabrican menos pigmento oscuro y más del rojo y amarillo.'),
     'nonsense': B('Not here: no stop signal appears.', 'Aquí no: no aparece ninguna señal de fin.')},
    [ex('cell', B('Pigments', 'Pigmentos'), B('Dark and red-yellow', 'Oscuro y rojo-amarillo'), B('Hair gets its colour from two pigments. The dark one is the main one in black and brown hair; the red-yellow one dominates in red hair.', 'El pelo recibe su color de dos pigmentos. El oscuro es el principal en el pelo negro y castaño; el rojo y amarillo domina en el pelo rojo.')),
     ex('dna', B('One receptor', 'Un receptor'), B('The switch of the dark pigment', 'El interruptor del pigmento oscuro'), B('When MC1R works well, it switches the cell towards the dark pigment. When two copies work less, the cell makes mostly the red-yellow one, which is why red hair is recessive.', 'Cuando MC1R funciona bien, inclina a la célula hacia el pigmento oscuro. Cuando dos copias funcionan menos, la célula fabrica sobre todo el rojo y amarillo, por eso el pelo rojo es recesivo.'))],
    [B('Compare the two rows letter by letter. Only one is different.', 'Compara las dos filas letra a letra. Solo una es distinta.'),
     B('Look at the codon that contains the changed letter, before and after.', 'Mira el codón que contiene la letra cambiada, antes y después.'),
     B('The change is in the third codon: CGC became TGC, so Arg became Cys (missense).', 'El cambio está en el tercer codón: CGC pasó a TGC, así que Arg pasó a Cys (de sentido erróneo).')],
    org('mc1r-gene', 'Pigment receptor', 'Receptor del pigmento', 'Homo sapiens', B('A protein that controls which pigment a hair cell makes.', 'Una proteína que controla qué pigmento fabrica una célula del pelo.'), MAMMAL + ['Primates', 'Hominidae', 'Homo'], tissue='hair follicle'),
    **closing(B('A letter that changes the colour', 'Una letra que cambia el color'),
              B('You found a one-letter change that swaps an amino acid and lowers the activity of a receptor.', 'Has encontrado un cambio de una letra que sustituye un aminoácido y reduce la actividad de un receptor.'),
              B('The same receptor family colours the coats of horses, dogs and cattle, so breeders and veterinarians use this knowledge to predict coat colours.', 'La misma familia de receptores colorea el pelaje de caballos, perros y ganado, así que quien los cría y los veterinarios usan este conocimiento para predecir colores.'),
              B('In 1995 a team showed that people with red hair carry changes in the MC1R gene. Several different changes were found, and the R151C swap is one of the most common.', 'En 1995 un equipo mostró que las personas con pelo rojo llevan cambios en el gen MC1R. Se encontraron varios cambios distintos, y el de R151C es uno de los más frecuentes.'),
              B('A missense mutation swaps one amino acid for another. Here the swap lowers the activity of a receptor, so the balance between the two pigments moves towards the red-yellow one.', 'Una mutación de sentido erróneo cambia un aminoácido por otro. Aquí el cambio reduce la actividad de un receptor, así que el equilibrio entre los dos pigmentos se mueve hacia el rojo y amarillo.'),
              [B('The real change is the one described, but the sequence around it is an invented short example.', 'El cambio real es el que se describe, pero la secuencia que lo rodea es un ejemplo corto inventado.')],
              [ref(['Valverde, P.', 'Healy, E.', 'Jackson, I.', 'Rees, J. L.', 'Thody, A. J.'], 1995, 'Variants of the melanocyte-stimulating hormone receptor gene are associated with red hair and fair skin in humans', 'Nature Genetics', '10.1038/ng1195-328')]))

# ═════════════════════════ PAIRING ═════════════════════════

BARCODE = 'CCTCTATCTAGTATT'
barcode_partner = ' '.join(COMP[c] for c in BARCODE)
pair_barcode = pair_spec('pair-barcode', B('A barcode for fish', 'Un código de barras para pescado'), B('Fifteen letters of a barcode gene', 'Quince letras de un gen código de barras'), 'beginner', 5, 'dna', BARCODE,
    B('Many species can be told apart by a short stretch of one gene, like a barcode. Copy this stretch, letter by letter, as a sequencing machine would.', 'Muchas especies se distinguen por un trozo corto de un gen, como un código de barras. Copia este trozo, letra a letra, como haría una máquina de secuenciar.'),
    B('Write the second strand of this stretch of a fish barcode gene.', 'Escribe la segunda hebra de este trozo de un gen código de barras de un pez.'),
    [B('Go from left to right and pair each letter on its own.', 'Ve de izquierda a derecha y empareja cada letra por separado.'),
     B('A pairs with T and C pairs with G, in both directions.', 'A se une con T y C con G, en los dos sentidos.'),
     B('The partners are: ' + barcode_partner + '.', 'Las parejas son: ' + barcode_partner + '.')],
    [ex('dna', B('The barcode', 'El código de barras'), B('A short gene, a clear name', 'Un gen corto, un nombre claro'), B('A gene of the mitochondria called COI changes a little from species to species. A stretch of about 650 letters is enough to tell most animals apart.', 'Un gen de las mitocondrias llamado COI cambia un poco de una especie a otra. Un trozo de unas 650 letras basta para distinguir a la mayoría de los animales.')),
     ex('bottle', B('At the shop', 'En la tienda'), B('Is it the fish on the label?', '¿Es el pescado de la etiqueta?'), B('A fillet or a can has no head, no fins and no skin. Its DNA still tells which fish it came from.', 'Un filete o una lata no tienen cabeza, ni aletas, ni piel. Su ADN sigue diciendo de qué pez viene.'))],
    **closing(B('Pairs for a barcode', 'Parejas para un código de barras'),
              B('You paired a stretch of a barcode gene: the same rules a sequencing machine uses when it reads DNA.', 'Has emparejado un trozo de un gen código de barras: las mismas reglas que usa una máquina de secuenciar cuando lee ADN.'),
              B('DNA barcodes are used to check the names of fish and other foods, to find species in the wild and to identify animals from tiny samples.', 'Los códigos de barras de ADN se usan para comprobar los nombres de pescados y otros alimentos, para encontrar especies en la naturaleza y para identificar animales a partir de muestras diminutas.'),
              B('In 2003 a team proposed using a short stretch of the COI gene as a universal barcode for animals. Today there are public libraries with millions of barcodes.', 'En 2003 un equipo propuso usar un trozo corto del gen COI como código de barras universal para los animales. Hoy existen bibliotecas públicas con millones de códigos.'),
              B('Hydrogen bonds hold A with T (two bonds) and G with C (three bonds). That is what lets a machine copy a strand again and again.', 'Los enlaces de hidrógeno mantienen unidas A con T (dos enlaces) y G con C (tres enlaces). Eso es lo que deja a una máquina copiar una hebra una y otra vez.'),
              B('The stretch is invented and much shorter than a real barcode of about 650 letters.', 'El trozo es inventado y mucho más corto que un código real de unas 650 letras.'),
              [ref(['Hebert, P. D. N.', 'Cywinska, A.', 'Ball, S. L.', 'deWaard, J. R.'], 2003, 'Biological identifications through DNA barcodes', 'Proceedings of the Royal Society B', '10.1098/rspb.2002.2218')]))

GFP_RNA = 'AUGAGUAAAGGAGAAGAACUUUUUUAA'
gfp_aminos = ', '.join(RNA_CODONS[GFP_RNA[i:i + 3]] for i in range(0, len(GFP_RNA), 3))
gfp_aminos_es = gfp_aminos.replace('Stop', 'Fin')
pair_gfp = pair_spec('pair-gfp', B('The first words of a glowing protein', 'Las primeras palabras de una proteína que brilla'), B('Eight codons and a stop', 'Ocho codones y una parada'), 'intermediate', 6, 'protein', GFP_RNA,
    B('Read the first codons of the message for the green fluorescent protein and find the amino acid of each.', 'Lee los primeros codones del mensaje de la proteína fluorescente verde y busca el aminoácido de cada uno.'),
    B('Read this messenger RNA three letters at a time and find the amino acid of each codon.', 'Lee este ARN mensajero de tres en tres letras y busca el aminoácido de cada codón.'),
    [B('Split the message into groups of three and look each one up in the table.', 'Divide el mensaje en grupos de tres y busca cada uno en la tabla.'),
     B('The first codon is AUG (start and methionine) and the last one is a stop.', 'El primer codón es AUG (inicio y metionina) y el último es de parada.'),
     B('The answers are: ' + gfp_aminos + '.', 'Las respuestas son: ' + gfp_aminos_es + '.')],
    [ex('jellyfish', B('The protein', 'La proteína'), B('Light from a jellyfish', 'Luz de una medusa'), B('The green fluorescent protein, GFP, is found in a jellyfish and glows green under blue light. Its first amino acids are Met, Ser, Lys, Gly, Glu, Glu, Leu and Phe.', 'La proteína fluorescente verde, GFP, se encuentra en una medusa y brilla en verde bajo luz azul. Sus primeros aminoácidos son Met, Ser, Lys, Gly, Glu, Glu, Leu y Phe.')),
     ex('dna', B('Why it matters', 'Por qué importa'), B('A lamp for living cells', 'Una lámpara para células vivas'), B('Scientists attach the gene of GFP to the gene of another protein, and the cell then shows where that protein is by glowing.', 'Los científicos pegan el gen de la GFP al gen de otra proteína, y la célula muestra entonces dónde está esa proteína al brillar.'))],
    **closing(B('The message of a glowing protein', 'El mensaje de una proteína que brilla'),
              B('You translated the beginning of the message for a protein that glows: a codon, an amino acid, and so on.', 'Has traducido el comienzo del mensaje de una proteína que brilla: un codón, un aminoácido, y así sucesivamente.'),
              B('Because the code is the same in all living things, the gene of a jellyfish works in bacteria, plants and animals.', 'Como el código es el mismo en todos los seres vivos, el gen de una medusa funciona en bacterias, plantas y animales.'),
              B('The beginning of the real GFP is Met-Ser-Lys-Gly-Glu-Glu-Leu-Phe-Thr-Gly. The RNA here is an invented message that codes for those amino acids.', 'El comienzo de la GFP real es Met-Ser-Lys-Gly-Glu-Glu-Leu-Phe-Thr-Gly. El ARN de aquí es un mensaje inventado que codifica esos aminoácidos.'),
              B('Most amino acids have several codons. The genetic code is shared by almost all living things.', 'La mayoría de los aminoácidos tiene varios codones. El código genético lo comparten casi todos los seres vivos.'),
              B('The real RNA may use other codons for the same amino acids.', 'El ARN real puede usar otros codones para los mismos aminoácidos.'),
              []))

