seq_cheese = seq_spec('seq-cheese', B('From milk to cheese', 'De la leche al queso'), B('Eight steps, each one needs the one before', 'Ocho pasos, cada uno necesita el anterior'), 'intermediate', 6, 'cheese',
    B('Put the steps of cheese making in order, and see why each one has to come when it does.', 'Pon en orden los pasos para hacer queso y descubre por qué cada uno tiene que llegar cuando llega.'),
    B('Cheese is milk that a bacterium and an enzyme have changed. The order matters: the bacteria need warm milk, and the enzyme needs the bacteria to have started their work.', 'El queso es leche que una bacteria y una enzima han transformado. El orden importa: las bacterias necesitan la leche templada, y la enzima necesita que las bacterias hayan empezado su trabajo.'),
    org('cheese-making', 'Milk, bacteria and rennet', 'Leche, bacterias y cuajo', 'Lactococcus lactis', B('A milk-souring bacterium that starts most cheeses.', 'Una bacteria que agria la leche y con la que empiezan casi todos los quesos.'), ['Bacteria', 'Bacillota', 'Bacilli', 'Lactobacillales', 'Streptococcaceae', 'Lactococcus'], tissue='milk'),
    [ex('milk', B('Milk', 'Leche'), B('Water, sugar, fat and casein', 'Agua, azúcar, grasa y caseína'), B('Casein is the main protein of milk. It floats as tiny balls, and cheese is made by getting them to stick together.', 'La caseína es la principal proteína de la leche. Flota en forma de bolitas diminutas, y el queso se hace consiguiendo que se peguen.')),
     ex('bacterium', B('Two helpers', 'Dos ayudantes'), B('Bacteria and rennet', 'Bacterias y cuajo'), B('Bacteria sour the milk by turning lactose into lactic acid. Rennet contains chymosin, an enzyme that snips casein so that the balls stick and a curd forms.', 'Las bacterias agrian la leche al convertir la lactosa en ácido láctico. El cuajo contiene quimosina, una enzima que corta la caseína para que las bolitas se peguen y se forme una cuajada.'))],
    [('warm', B('Warm the milk gently', 'Calentar suavemente la leche'), B('The milk reaches a temperature where bacteria and enzymes work well.', 'La leche llega a una temperatura en la que las bacterias y las enzimas trabajan bien.'), NOTHING),
     ('starter', B('Add a starter of lactic acid bacteria', 'Añadir un fermento de bacterias lácticas'), B('The bacteria begin to turn lactose into lactic acid.', 'Las bacterias empiezan a convertir la lactosa en ácido láctico.'), B('The milk has to be warm first, so the bacteria can grow.', 'La leche tiene que estar templada antes, para que las bacterias puedan crecer.')),
     ('rennet', B('Add rennet, which contains the enzyme chymosin', 'Añadir cuajo, que contiene la enzima quimosina'), B('Chymosin snips the casein that keeps the milk balls apart.', 'La quimosina corta la caseína que mantiene separadas las bolitas de la leche.'), B('The starter has to have begun to sour the milk.', 'El fermento tiene que haber empezado a agriar la leche.')),
     ('curd', B('Wait until the milk sets into a curd', 'Esperar a que la leche cuaje'), B('The milk balls stick together into a soft solid.', 'Las bolitas de la leche se pegan y forman un sólido blando.'), B('The rennet has to be in the milk first.', 'El cuajo tiene que estar ya en la leche.')),
     ('cut', B('Cut the curd into small pieces', 'Cortar la cuajada en trozos pequeños'), B('The pieces let the liquid leave.', 'Los trozos dejan salir el líquido.'), B('There has to be a curd to cut.', 'Tiene que haber una cuajada que cortar.')),
     ('drain', B('Drain the whey', 'Escurrir el suero'), B('Most of the water leaves and the curd becomes firmer.', 'Sale casi toda el agua y la cuajada se vuelve más firme.'), B('The curd has to be cut so that the whey can leave.', 'La cuajada tiene que estar cortada para que el suero pueda salir.')),
     ('press', B('Press and salt the curd', 'Prensar y salar la cuajada'), B('The curd is shaped into a block, and the salt protects it.', 'La cuajada toma forma de bloque, y la sal la protege.'), B('The whey has to be gone first.', 'El suero tiene que haberse ido antes.')),
     ('age', B('Let it age for weeks or months', 'Dejarlo madurar durante semanas o meses'), B('Microbes and enzymes slowly change flavour and texture.', 'Microbios y enzimas cambian poco a poco el sabor y la textura.'), B('The cheese has to be pressed and salted first.', 'El queso tiene que estar prensado y salado antes.'))],
    B('Cheese', 'Queso'),
    [B('Think about what each helper needs: the bacteria need warmth, and the enzyme needs a milk that is already souring.', 'Piensa en lo que necesita cada ayudante: las bacterias necesitan calor y la enzima necesita una leche que ya se esté agriando.'),
     B('Warm, bacteria, rennet, curd, then cut, drain, press and age.', 'Calentar, bacterias, cuajo, cuajada, y después cortar, escurrir, prensar y madurar.'),
     B('Warm → starter → rennet → curd → cut → drain → press → age.', 'Calentar → fermento → cuajo → cuajada → cortar → escurrir → prensar → madurar.')],
    **closing(B('A chain of changes', 'Una cadena de cambios'),
              B('You followed the steps that turn milk into cheese, each one preparing the next.', 'Has seguido los pasos que convierten la leche en queso, cada uno preparando el siguiente.'),
              B('Cheese is one of the oldest foods made with biotechnology, and thousands of varieties come from changing one step of this chain.', 'El queso es uno de los alimentos más antiguos hechos con biotecnología, y miles de variedades salen de cambiar un paso de esta cadena.'),
              B('Rennet was traditionally taken from the stomach of calves. Since 1990 most of the chymosin used in cheese has been made by microbes carrying the calf gene, which is how one of the first food ingredients made with genetic engineering reached the shops.', 'El cuajo se sacaba tradicionalmente del estómago de los terneros. Desde 1990 la mayor parte de la quimosina que se usa en el queso la fabrican microbios que llevan el gen del ternero, y así llegó a las tiendas uno de los primeros ingredientes alimentarios hechos con ingeniería genética.'),
              B('Chymosin cuts one specific bond of kappa-casein, the protein that coats the milk balls. Without that coat the balls stick together, and with acid and heat they form a gel.', 'La quimosina corta un enlace concreto de la kappa-caseína, la proteína que recubre las bolitas de la leche. Sin esa cubierta las bolitas se pegan, y con ácido y calor forman un gel.'),
              B('Every cheese has its own recipe; the order of the main steps is the common part.', 'Cada queso tiene su propia receta; el orden de los pasos principales es la parte común.'),
              []))

seq_barcode = seq_spec('seq-barcode', B('Is it the fish on the label?', '¿Es el pescado de la etiqueta?'), B('From a fillet to a name, step by step', 'De un filete a un nombre, paso a paso'), 'intermediate', 6, 'dna',
    B('Put the steps of a DNA barcode test in order and see how a laboratory names a fish from a small piece.', 'Pon en orden los pasos de una prueba de código de barras de ADN y descubre cómo un laboratorio nombra un pez a partir de un trozo pequeño.'),
    B('Fish fillets all look alike. A laboratory can tell what species a fillet comes from by reading a short stretch of its DNA.', 'Todos los filetes de pescado se parecen. Un laboratorio puede decir de qué especie es un filete leyendo un trozo corto de su ADN.'),
    org('fish-barcode', 'A fillet and a library', 'Un filete y una biblioteca', 'DNA barcoding', B('A method that names a species from a short DNA sequence.', 'Un método que nombra una especie a partir de una secuencia corta de ADN.'), ['Method'], tissue='muscle'),
    [ex('bottle', B('The question', 'La pregunta'), B('A name on a label', 'Un nombre en una etiqueta'), B('When fish is sold as fillets or as a cooked dish, the buyer cannot check the species. A test can.', 'Cuando el pescado se vende en filetes o en un plato cocinado, quien compra no puede comprobar la especie. Una prueba sí puede.')),
     ex('dna', B('The method', 'El método'), B('Read, then compare', 'Leer y comparar'), B('A short stretch of the COI gene is read and compared with a public library of barcodes of known species. The best match gives the name.', 'Se lee un trozo corto del gen COI y se compara con una biblioteca pública de códigos de especies conocidas. La mejor coincidencia da el nombre.'))],
    [('sample', B('Take a tiny piece of the fish', 'Tomar un trocito del pescado'), B('A few milligrams are enough.', 'Bastan unos pocos miligramos.'), NOTHING),
     ('extract', B('Extract the DNA from the sample', 'Extraer el ADN de la muestra'), B('The cells are opened and the DNA is cleaned.', 'Se abren las células y se limpia el ADN.'), B('There must be a sample to open.', 'Tiene que haber una muestra que abrir.')),
     ('pcr', B('Copy the barcode region with PCR', 'Copiar la región del código con PCR'), B('Millions of copies of just that stretch are made.', 'Se hacen millones de copias de ese trozo.'), B('The DNA has to be extracted first.', 'El ADN tiene que estar extraído antes.')),
     ('read', B('Read the letters of the copies in a sequencer', 'Leer las letras de las copias en un secuenciador'), B('The machine gives the sequence of the barcode.', 'La máquina da la secuencia del código.'), B('The copies have to exist first.', 'Las copias tienen que existir antes.')),
     ('compare', B('Compare the sequence with a library of barcodes', 'Comparar la secuencia con una biblioteca de códigos'), B('Software looks for the most similar barcodes.', 'Un programa busca los códigos más parecidos.'), B('The sequence has to be read first.', 'La secuencia tiene que estar leída antes.')),
     ('name', B('Name the species with the best match', 'Nombrar la especie de mejor coincidencia'), B('The result is a species name.', 'El resultado es el nombre de una especie.'), B('The comparison has to be done first.', 'La comparación tiene que estar hecha antes.')),
     ('check', B('Check the name against the label', 'Comprobar el nombre con la etiqueta'), B('If they do not agree, the fish was sold under the wrong name.', 'Si no coinciden, el pescado se vendió con un nombre equivocado.'), B('You need the name of the species first.', 'Necesitas antes el nombre de la especie.'))],
    B('Species name', 'Nombre de la especie'),
    [B('The test goes from the sample to the DNA, to many copies, to a sequence, to a name.', 'La prueba va de la muestra al ADN, a muchas copias, a una secuencia y a un nombre.'),
     B('Sample, extract, copy, read, compare, name and, last of all, check the label.', 'Muestra, extraer, copiar, leer, comparar, nombrar y, por último, comprobar la etiqueta.'),
     B('Sample → extract → PCR → read → compare → name → check.', 'Muestra → extraer → PCR → leer → comparar → nombrar → comprobar.')],
    **closing(B('A name from a piece of DNA', 'Un nombre a partir de un trozo de ADN'),
              B('You followed the steps that name a species from a tiny sample, without needing to see the animal.', 'Has seguido los pasos que nombran una especie a partir de una muestra diminuta, sin necesidad de ver el animal.'),
              B('The same method is used by food inspectors, by people who study wildlife and by museums that need to name old specimens.', 'El mismo método lo usan quienes inspeccionan alimentos, quienes estudian la fauna y los museos que necesitan nombrar ejemplares antiguos.'),
              B('Studies of fish sold in North American shops and restaurants found that a share of the samples were sold under a name that did not match the species found by barcoding.', 'Estudios de pescado vendido en tiendas y restaurantes de Norteamérica encontraron que una parte de las muestras se vendía con un nombre que no coincidía con la especie hallada por el código de barras.'),
              B('PCR copies only the region between two short primers, so the same primers work for many species. Public libraries hold barcodes of hundreds of thousands of species.', 'La PCR copia solo la región entre dos cebadores cortos, así que los mismos cebadores sirven para muchas especies. Las bibliotecas públicas guardan códigos de cientos de miles de especies.'),
              B('A real laboratory also controls for contamination and checks both strands of the DNA.', 'Un laboratorio real también controla la contaminación y revisa las dos hebras del ADN.'),
              [ref(['Hebert, P. D. N.', 'Cywinska, A.', 'Ball, S. L.', 'deWaard, J. R.'], 2003, 'Biological identifications through DNA barcodes', 'Proceedings of the Royal Society B', '10.1098/rspb.2002.2218'),
               ref(['Wong, E. H.-K.', 'Hanner, R. H.'], 2008, 'DNA barcoding detects market substitution in North American seafood', 'Food Research International', '10.1016/j.foodres.2008.07.005')]))

